def safe_flow_from_directory(self, *args, **kwargs):
    original_generator = self.flow_from_directory(*args, **kwargs)
    class SafeIterator(type(original_generator)):
        def __next__(self):
            while True:
                try:
                    return super().__next__()
                except Exception as e:
                    print(f"Warning: Skipping batch due to error: {str(e)}")
                    continue
    return SafeIterator(*original_generator.args, **original_generator.kwargs)

