# Custom generator that skips errors
def safe_generator(generator):
    while True:
        try:
            data, labels = next(generator)
            yield data, labels
        except StopIteration:
            raise
        except Exception as e:
            print(f"Warning: Skipping problematic batch due to error: {type(e).__name__}")
            traceback.print_exc()
            continue

